"""Random arrays, including some entirely on one side of zero, since that is
exactly what a wrongly-seeded min/max misses."""


def generate(rng, count):
    builders = (_mixed, _all_negative, _all_positive, _single_element)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, values, description=""):
    return {"name": name,
            "stdin": "%d\n%s\n" % (len(values), " ".join(map(str, values))),
            "description": description}


def _mixed(rng, index):
    n = rng.randint(1, 30)
    values = [rng.randint(-1000, 1000) for _ in range(n)]
    return _case("a %d-element array spanning both signs #%d" % (n, index), values)


def _all_negative(rng, index):
    n = rng.randint(1, 15)
    values = [rng.randint(-1000, -1) for _ in range(n)]
    return _case("an all-negative array #%d" % index, values)


def _all_positive(rng, index):
    n = rng.randint(1, 15)
    values = [rng.randint(1, 1000) for _ in range(n)]
    return _case("an all-positive array #%d" % index, values)


def _single_element(rng, index):
    value = rng.randint(-1000, 1000)
    return _case("a single-element array #%d" % index, [value])
